1	/**
2	 * Sitewave — seed the starter per-vertical template library.
3	 *
4	 * Idempotent: upserts each vertical by slug and ensures it has its starter
5	 * template. Safe to re-run. NOT run automatically by any deploy; run manually
6	 * against a chosen target, exactly like prisma/seed.ts:
7	 *
8	 *   NXEON_DB_TARGET=nxeon_staging npx tsx prisma/seed-agency.ts
9	 *
10	 * The template `structure` mirrors lib/agency/templates.ts so the DB library and
11	 * the generator's deterministic fallback stay in lockstep.
12	 */
13	
14	import { PrismaClient } from "@prisma/client";
15	import { assertDbTarget } from "../scripts/db-target-guard.ts";
16	import { VERTICALS } from "../lib/agency/templates.ts";
17	
18	assertDbTarget("prisma/seed-agency.ts");
19	
20	const db = new PrismaClient();
21	
22	async function main() {
23	  for (const v of VERTICALS) {
24	    const vertical = await db.agencyVertical.upsert({
25	      where: { slug: v.slug },
26	      update: { name: v.name, description: v.description },
27	      create: { slug: v.slug, name: v.name, description: v.description },
28	    });
29	
30	    const existing = await db.agencyTemplate.findFirst({
31	      where: { verticalId: vertical.id, name: v.templateName },
32	      select: { id: true },
33	    });
34	    if (existing) {
35	      await db.agencyTemplate.update({
36	        where: { id: existing.id },
37	        data: { structure: v.structure as object },
38	      });
39	    } else {
40	      await db.agencyTemplate.create({
41	        data: { verticalId: vertical.id, name: v.templateName, structure: v.structure as object },
42	      });
43	    }
44	    console.log(`seeded vertical + template: ${v.slug}`);
45	  }
46	}
47	
48	main()
49	  .then(() => db.$disconnect())
50	  .catch(async (err) => {
51	    console.error(err);
52	    await db.$disconnect();
53	    process.exit(1);
54	  });
