enum AgencyProspectStatus {
  PROSPECT
  GENERATED
  SENT
  WON
  LOST
}

/// Lifecycle of a generated spec-site demo. DRAFT is reserved for a queued-but-
/// unrendered demo; Phase 1 writes GENERATED once the renderer runs. A
/// "Deploy to subdomain" click only marks DEPLOYED_STUB (records the intended
/// slug) — real provisioning is Phase 2.
enum AgencyDemoStatus {
  DRAFT
  GENERATED
  DEPLOYED_STUB
}

/// A business vertical (dentist, restaurant, gym, law firm, salon…). Seeded by
/// prisma/seed-agency.ts. Each vertical owns one or more templates.
model AgencyVertical {
  id          String   @id @default(cuid())
  slug        String   @unique
  name        String
  description String   @default("")
  createdAt   DateTime @default(now())

  templates AgencyTemplate[]

  @@index([slug])
}

/// A per-vertical site template: a JSON section-schema describing which sections
/// the generated site is constrained to (hero, services, about, testimonials,
/// contact) plus per-section copy guidance. The generator plans against this.
model AgencyTemplate {
  id         String   @id @default(cuid())
  verticalId String
  name       String
  /// Section schema + prompt guidance. Shape: { sections: [{ key, label,
  /// required, fields: [...] }], palette?: {...} }. Validated in lib/agency/schema.ts.
  structure  Json     @default("{}")
  createdAt  DateTime @default(now())

  vertical AgencyVertical    @relation(fields: [verticalId], references: [id], onDelete: Cascade)
  demos    AgencyDemoSite[]

  @@index([verticalId])
  @@index([createdAt])
}

/// A target business. Manual add or CSV paste only in Phase 1 — no scraping, no
/// enrichment. `vertical` is a plain slug string (not a FK) so a prospect can be
/// added before its vertical exists; the generator resolves it at gen time.
model AgencyProspect {
  id             String               @id @default(cuid())
  businessName   String
  vertical       String               @default("")
  contactEmail   String?
  currentSiteUrl String?
  /// Optional pasted text from the prospect's existing site. NEVER scraped —
  /// an operator pastes it. Feeds the generator as context only.
  pastedSiteText String               @default("")
  notes          String               @default("")
  status         AgencyProspectStatus @default(PROSPECT)
  /// Set once "Send to outreach" links this prospect to a Cold Email Business.
  outreachBusinessId String?
  createdAt      DateTime             @default(now())

  demos AgencyDemoSite[]

  @@index([status])
  @@index([vertical])
  @@index([createdAt])
}

/// A generated spec-site demo for a prospect. Stores the structured Site IR and
/// the deterministically rendered self-contained HTML. `slug` is the would-be
/// subdomain label (slug.agency.revsports.ca) — recorded, never provisioned in
/// Phase 1. `noindex` defaults true and the renderer always emits the robots
/// meta + affiliation disclaimer (legal guardrails).
model AgencyDemoSite {
  id           String           @id @default(cuid())
  prospectId   String
  templateId   String?
  /// Structured Site IR (hero copy, services, about, CTA, palette suggestion).
  siteIR       Json             @default("{}")
  renderedHtml String           @default("")
  slug         String
  status       AgencyDemoStatus @default(DRAFT)
  noindex      Boolean          @default(true)
  /// Recorded when "Deploy to subdomain" is clicked (the intended host). Real
  /// provisioning is Phase 2 — this is documentation of intent only.
  intendedHost String?
  deployedAt   DateTime?
  createdAt    DateTime         @default(now())

  prospect AgencyProspect      @relation(fields: [prospectId], references: [id], onDelete: Cascade)
  template AgencyTemplate?     @relation(fields: [templateId], references: [id], onDelete: SetNull)
  logs     AgencyGenerationLog[]

  @@index([prospectId])
  @@index([status])
  @@index([slug])
  @@index([createdAt])
}

/// Append-only audit of a generation attempt: which path ran (llm | fallback),
/// the model, an outcome, and a short message. One demo can have many logs
/// (e.g. a re-generation).
model AgencyGenerationLog {
  id        String   @id @default(cuid())
  demoId    String
  /// "llm" when askClaude produced the IR, "fallback" when the deterministic
  /// template fill was used (no ANTHROPIC_API_KEY or an API error).
  mode      String   @default("fallback")
  model     String   @default("")
  ok        Boolean  @default(true)
  message   String   @default("")
  createdAt DateTime @default(now())

  demo AgencyDemoSite @relation(fields: [demoId], references: [id], onDelete: Cascade)

  @@index([demoId])
  @@index([createdAt])
}
