48	/** A button that runs a (id) => Promise action inside a transition. */
49	function ActionButton({
50	  run,
51	  children,
52	  className = "",
53	  confirm,
54	  title,
55	}: {
56	  run: () => Promise<State>;
57	  children: React.ReactNode;
58	  className?: string;
59	  confirm?: string;
60	  title?: string;
61	}) {
62	  const [pending, start] = useTransition();
63	  const [err, setErr] = useState<string | null>(null);
64	  return (
65	    <span className="inline-flex flex-col items-end">
66	      <button
67	        type="button"
68	        disabled={pending}
69	        title={title}
70	        className={className || "btn-ghost text-xs"}
71	        onClick={() => {
72	          if (confirm && !window.confirm(confirm)) return;
73	          setErr(null);
74	          start(async () => {
75	            const r = await run();
76	            if (r?.error) setErr(r.error);
