/**
 * Adloop — brand + module configuration.
 *
 * PLACEHOLDER BRAND. "Adloop" is a working name for the cross-platform paid-ads
 * management add-on. The domain is stored here as config only — it is NOT
 * resolved via DNS and nothing is provisioned in Phase 1.
 */

export const ADLOOP = {
