/**
 * Adloop — the unified, platform-agnostic type layer.
 *
 * These types are the single normalized shape that the three platform
 * connectors (Meta / TikTok / Google) map into. Nothing here imports Prisma or
 * touches the network — it is the pure contract shared by the connector seam,
 * the rules engine and the reporting layer.
 */

import type { AdsPlatformKey } from "./config";

// ---------------------------------------------------------------------------
// Canonical metrics
// ---------------------------------------------------------------------------

/** The raw daily counters we store (mirrors the AdsInsight model). */
export type InsightCounters = {
  impressions: number;
  clicks: number;
  spendCents: number;
  conversions: number;
};

/**
 * The derived, unit-normalized metric set every rule + report speaks in.
 * Money is in whole currency units (dollars), not cents. Ratios that would
 * divide by zero are reported as null (never NaN/Infinity).
 */
export type DerivedMetrics = {
  impressions: number;
  clicks: number;
  spend: number; // dollars
  conversions: number;
  ctr: number | null; // clicks / impressions
  cpc: number | null; // spend / clicks
  cpm: number | null; // spend / impressions * 1000
  cpa: number | null; // spend / conversions
  cvr: number | null; // conversions / clicks
};

/** The metric keys a rule may condition on (only the computable ones). */
export const RULE_METRICS = [
  "spend",
  "impressions",
  "clicks",
  "conversions",
  "ctr",
  "cpc",
  "cpm",
  "cpa",
  "cvr",
] as const;
export type RuleMetric = (typeof RULE_METRICS)[number];

// ---------------------------------------------------------------------------
// Rules
// ---------------------------------------------------------------------------

export const RULE_OPERATORS = ["gt", "gte", "lt", "lte", "eq"] as const;
export type RuleOperator = (typeof RULE_OPERATORS)[number];

export const RULE_ACTIONS = [
  "pause",
  "enable",
  "raise_budget",
  "lower_budget",
  "notify",
] as const;
export type RuleAction = (typeof RULE_ACTIONS)[number];

/** The `whenJson` shape: a single metric comparison over a lookback window. */
export type RuleCondition = {
  metric: RuleMetric;
  operator: RuleOperator;
  threshold: number;
  /** Lookback window in days for the insight aggregate (default 7). */
  lookbackDays?: number;
  /** Significance floor — do not act below this many impressions (default 0). */
  minImpressions?: number;
};

/** The `thenJson` shape: the action a matched rule WOULD take (dry-run only). */
export type RuleThen = {
  action: RuleAction;
  /** Percentage change for raise_budget / lower_budget (e.g. 20 = +20%). */
  amountPct?: number;
};

// ---------------------------------------------------------------------------
// Connector seam
// ---------------------------------------------------------------------------

/** A normalized account as a connector would return it. */
export type NormalizedAccount = {
  platform: AdsPlatformKey;
  externalId: string;
  name: string;
};

/** A normalized campaign as a connector would return it. */
export type NormalizedCampaign = {
  externalId: string;
  name: string;
  objective: string;
  dailyBudgetCents: number;
  status: string;
};

/**
 * Every connector method returns one of these. In Phase 1 connectors are stubs,
 * so `ok` is always false with reason "not_connected" / "pending_approval" and
 * no `data` — proving the seam without any network call.
 */
export type ConnectorResult<T> =
  | { ok: true; data: T }
  | { ok: false; reason: ConnectorNotReady; message: string };

export type ConnectorNotReady = "not_connected" | "pending_approval" | "not_implemented";

/**
 * The pluggable connector interface. A real Phase-2+ implementation would talk
 * to the platform API here; the Phase-1 stubs return typed not-ready results.
 * NOTE the deliberate absence of any mutating "applyAction" that touches a live
 * platform — Phase 1 rules are dry-run only.
 */
export interface AdsConnector {
  readonly platform: AdsPlatformKey;
  /** Discover ad accounts the connected user can manage. */
  listAccounts(): Promise<ConnectorResult<NormalizedAccount[]>>;
  /** List campaigns under an external account id. */
  listCampaigns(externalAccountId: string): Promise<ConnectorResult<NormalizedCampaign[]>>;
  /** Pull daily insight counters for an external entity id. */
  fetchInsights(
    externalEntityId: string,
    lookbackDays: number,
  ): Promise<ConnectorResult<InsightCounters[]>>;
}

/**
 * Adloop — metric derivation. Pure functions, no I/O.
 *
 * Turns raw daily counters into the canonical derived metric set. All ratios
 * guard against divide-by-zero by returning `null` (never NaN/Infinity), so the
 * rules engine and reports can decide how to treat "no data" explicitly.
 */

import type { InsightCounters, DerivedMetrics, RuleMetric } from "./types";

/** Sum a list of daily counters into one aggregate. */
export function sumCounters(rows: InsightCounters[]): InsightCounters {
  return rows.reduce<InsightCounters>(
    (acc, r) => ({
      impressions: acc.impressions + (r.impressions || 0),
      clicks: acc.clicks + (r.clicks || 0),
      spendCents: acc.spendCents + (r.spendCents || 0),
      conversions: acc.conversions + (r.conversions || 0),
    }),
    { impressions: 0, clicks: 0, spendCents: 0, conversions: 0 },
  );
}

function ratio(numerator: number, denominator: number): number | null {
  if (!denominator || denominator <= 0) return null;
  return numerator / denominator;
}

/** Derive the canonical unit-normalized metrics from a counter aggregate. */
export function deriveMetrics(c: InsightCounters): DerivedMetrics {
  const spend = c.spendCents / 100;
  return {
    impressions: c.impressions,
    clicks: c.clicks,
    spend,
    conversions: c.conversions,
    ctr: ratio(c.clicks, c.impressions),
    cpc: ratio(spend, c.clicks),
    cpm: c.impressions > 0 ? (spend / c.impressions) * 1000 : null,
    cpa: ratio(spend, c.conversions),
    cvr: ratio(c.conversions, c.clicks),
  };
}

/** Pull a single derived metric by key (used by the rules engine). */
export function metricValue(m: DerivedMetrics, key: RuleMetric): number | null {
  return m[key];
}

/** Human-readable formatting for a metric value (dashboards + rule notes). */
export function formatMetric(key: RuleMetric, value: number | null): string {
  if (value === null) return "—";
  switch (key) {
    case "spend":
    case "cpc":
    case "cpa":
      return `$${value.toFixed(2)}`;
    case "cpm":
      return `$${value.toFixed(2)} CPM`;
    case "ctr":
    case "cvr":
      return `${(value * 100).toFixed(2)}%`;
    default:
      return value.toLocaleString();
  }
}

/**
 * Adloop — the rules-engine evaluator. PURE + testable. DRY-RUN ONLY.
 *
 * Given a rule's `whenJson` condition and an insight aggregate, decide whether
 * the rule matches and what action it WOULD take. This module NEVER executes a
 * real platform mutation — in Phase 1 the whole product is dry-run, and the
 * connector seam deliberately exposes no live "applyAction". The output of
 * `evaluateRule` is a description an operator (or a future scheduler) reads.
 *
 * Nothing here touches the network, the clock, or the database. Every input is
 * coerced through defaulting helpers so malformed JSON from the DB can never
 * throw.
 */

import {
  RULE_METRICS,
  RULE_OPERATORS,
  RULE_ACTIONS,
  type RuleCondition,
  type RuleThen,
  type RuleMetric,
  type RuleOperator,
  type RuleAction,
  type InsightCounters,
} from "./types";
import { deriveMetrics, metricValue, formatMetric } from "./metrics";

// ---------------------------------------------------------------------------
// Coercion — never throws, always yields a well-formed condition/action
// ---------------------------------------------------------------------------

function asRecord(v: unknown): Record<string, unknown> {
  return v && typeof v === "object" && !Array.isArray(v) ? (v as Record<string, unknown>) : {};
}

function asNumber(v: unknown, fallback: number): number {
  const n = typeof v === "number" ? v : typeof v === "string" ? Number(v) : NaN;
  return Number.isFinite(n) ? n : fallback;
}

/** Coerce arbitrary JSON into a valid RuleCondition (defaults fill the gaps). */
export function coerceCondition(json: unknown): RuleCondition {
  const o = asRecord(json);
  const metric = (RULE_METRICS as readonly string[]).includes(String(o.metric))
    ? (o.metric as RuleMetric)
    : "cpa";
  const operator = (RULE_OPERATORS as readonly string[]).includes(String(o.operator))
    ? (o.operator as RuleOperator)
    : "gt";
  return {
    metric,
    operator,
    threshold: asNumber(o.threshold, 0),
    lookbackDays: Math.max(1, Math.round(asNumber(o.lookbackDays, 7))),
    minImpressions: Math.max(0, Math.round(asNumber(o.minImpressions, 0))),
  };
}

/** Coerce arbitrary JSON into a valid RuleThen action. */
export function coerceThen(json: unknown): RuleThen {
  const o = asRecord(json);
  const action = (RULE_ACTIONS as readonly string[]).includes(String(o.action))
    ? (o.action as RuleAction)
    : "notify";
  const then: RuleThen = { action };
  if (action === "raise_budget" || action === "lower_budget") {
    then.amountPct = Math.max(0, asNumber(o.amountPct, 20));
  }
  return then;
}

// ---------------------------------------------------------------------------
// Evaluation
// ---------------------------------------------------------------------------

const OP_LABEL: Record<RuleOperator, string> = {
  gt: ">",
  gte: "≥",
  lt: "<",
  lte: "≤",
  eq: "=",
};

function compare(value: number, op: RuleOperator, threshold: number): boolean {
  switch (op) {
    case "gt":
      return value > threshold;
    case "gte":
      return value >= threshold;
    case "lt":
      return value < threshold;
    case "lte":
      return value <= threshold;
    case "eq":
      return value === threshold;
  }
}

/** Describe what a matched action would do, in plain language (dry-run copy). */
export function describeAction(then: RuleThen): string {
  switch (then.action) {
    case "pause":
      return "pause the entity";
    case "enable":
      return "enable the entity";
    case "raise_budget":
      return `raise the daily budget by ${then.amountPct ?? 0}%`;
    case "lower_budget":
      return `lower the daily budget by ${then.amountPct ?? 0}%`;
    case "notify":
      return "send a notification";
  }
}

export type RuleEvaluation = {
  matched: boolean;
  /** The computed metric value the condition was tested against (null = no data). */
  computed: number | null;
  /** True when the significance floor (minImpressions) blocked evaluation. */
  belowFloor: boolean;
  /** The action that WOULD be taken (only meaningful when matched). */
  wouldDo: RuleAction | null;
  /** A one-line human summary suitable for AdsRuleRun.note. */
  note: string;
};

/**
 * Evaluate a rule against a set of daily insight rows (already scoped/filtered
 * to the entity + lookback window by the caller). Pure — returns a description
 * only; performs NO mutation. This is the heart of the "Test rule (dry-run)"
 * button.
 */
export function evaluateRule(
  whenJson: unknown,
  thenJson: unknown,
  rows: InsightCounters[],
): RuleEvaluation {
  const cond = coerceCondition(whenJson);
  const then = coerceThen(thenJson);

  const agg = rows.reduce<InsightCounters>(
    (a, r) => ({
      impressions: a.impressions + (r.impressions || 0),
      clicks: a.clicks + (r.clicks || 0),
      spendCents: a.spendCents + (r.spendCents || 0),
      conversions: a.conversions + (r.conversions || 0),
    }),
    { impressions: 0, clicks: 0, spendCents: 0, conversions: 0 },
  );

  const derived = deriveMetrics(agg);
  const computed = metricValue(derived, cond.metric);
  const condStr = `${cond.metric} ${OP_LABEL[cond.operator]} ${formatMetric(cond.metric, cond.threshold)}`;

  // Significance floor — refuse to act on noisy/insufficient data.
  if (agg.impressions < (cond.minImpressions ?? 0)) {
    return {
      matched: false,
      computed,
      belowFloor: true,
      wouldDo: null,
      note: `Below significance floor (${agg.impressions} < ${cond.minImpressions} impressions) — not evaluated. Would test ${condStr}.`,
    };
  }

  // No data for the chosen metric (e.g. CPA with zero conversions).
  if (computed === null) {
    return {
      matched: false,
      computed: null,
      belowFloor: false,
      wouldDo: null,
      note: `No ${cond.metric} data over the last ${cond.lookbackDays} day(s) — condition (${condStr}) could not be computed.`,
    };
  }

  const matched = compare(computed, cond.operator, cond.threshold);
  const actual = formatMetric(cond.metric, computed);

  if (matched) {
    return {
      matched: true,
      computed,
      belowFloor: false,
      wouldDo: then.action,
      note: `MATCH: ${cond.metric} is ${actual} (${condStr}) → would ${describeAction(then)}. DRY-RUN — no change made.`,
    };
  }

  return {
    matched: false,
    computed,
    belowFloor: false,
    wouldDo: null,
    note: `No match: ${cond.metric} is ${actual}, condition ${condStr} not met.`,
  };
}

/**
 * Adloop — the pluggable connector registry.
 *
 * `getConnector(platform)` returns the connector for a platform. In Phase 1
 * every connector is a STUB (see ./stub.ts) that returns typed not-ready
 * results and makes NO network call. When a platform's API access clears, swap
 * its entry here for a real implementation — nothing else in the codebase needs
 * to change, because everything speaks the `AdsConnector` interface.
 */

import type { AdsConnector } from "../types";
import type { AdsPlatformKey } from "../config";
import { MetaConnector } from "./meta";
import { TikTokConnector } from "./tiktok";
import { GoogleConnector } from "./google";

const REGISTRY: Record<AdsPlatformKey, AdsConnector> = {
  META: new MetaConnector(),
  TIKTOK: new TikTokConnector(),
  GOOGLE: new GoogleConnector(),
};

export function getConnector(platform: AdsPlatformKey): AdsConnector {
  return REGISTRY[platform];
}

export { MetaConnector } from "./meta";
export { TikTokConnector } from "./tiktok";
export { GoogleConnector } from "./google";

/**
 * Adloop — the shared STUB connector base.
 *
 * A `StubConnector` implements the full `AdsConnector` interface but every
 * method resolves to a typed `{ ok: false, reason: "pending_approval" }` result
 * with NO network call, NO OAuth, and NO ad spend. This is the entire Phase-1
 * behaviour: it proves the seam and the normalized types compile end-to-end
 * while real platform access is still gated on weeks-long approvals.
 *
 * Each real platform connector extends this and only needs to override methods
 * as its API access clears — until then it inherits the safe stub behaviour.
 */

import type {
  AdsConnector,
  ConnectorResult,
  NormalizedAccount,
  NormalizedCampaign,
  InsightCounters,
  ConnectorNotReady,
} from "../types";
import type { AdsPlatformKey } from "../config";

export abstract class StubConnector implements AdsConnector {
  abstract readonly platform: AdsPlatformKey;
  /** Human label used in the not-ready message. */
  protected abstract readonly label: string;
  /** Why this connector is not ready (defaults to pending platform approval). */
  protected readonly reason: ConnectorNotReady = "pending_approval";

  protected notReady<T>(op: string): ConnectorResult<T> {
    return {
      ok: false,
      reason: this.reason,
      message: `${this.label} ${op} is unavailable — pending platform API approval. No live call was made (Phase 1 scaffold).`,
    };
  }

  async listAccounts(): Promise<ConnectorResult<NormalizedAccount[]>> {
    return this.notReady("account discovery");
  }

  async listCampaigns(_externalAccountId: string): Promise<ConnectorResult<NormalizedCampaign[]>> {
    return this.notReady("campaign listing");
  }

  async fetchInsights(
    _externalEntityId: string,
    _lookbackDays: number,
  ): Promise<ConnectorResult<InsightCounters[]>> {
    return this.notReady("insight sync");
  }
}

