"use server";

/**
 * Adloop (Ads Autopilot) — admin server actions. PHASE 1.
 *
 * Every export re-checks `requireArea("platform")`. HARD GUARDRAILS enforced
 * here: NOTHING in this file makes a live call to Meta / TikTok / Google, runs
 * OAuth, or spends money. "Connect" only marks an account CONNECTED_STUB.
 * Campaigns / ad sets / creatives / ads are local drafts. "Test rule" runs the
 * pure DRY-RUN evaluator against sample/stub insights and only records a note —
 * it never executes a platform mutation.
 */

import { revalidatePath } from "next/cache";
import { z } from "zod";
import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { logEvent } from "@/lib/log";
import { evaluateRule } from "@/lib/ads/rules-engine";
import { RULE_METRICS, RULE_OPERATORS, RULE_ACTIONS } from "@/lib/ads/types";
import type { InsightCounters } from "@/lib/ads/types";
import type { Prisma } from "@prisma/client";

type ActionState = { error?: string; ok?: boolean; note?: string };

const PLATFORMS = ["META", "TIKTOK", "GOOGLE"] as const;
const ENTITY_STATUSES = ["DRAFT", "ACTIVE", "PAUSED", "ARCHIVED"] as const;

// ---------------------------------------------------------------------------
// Accounts
// ---------------------------------------------------------------------------

const accountSchema = z.object({
  platform: z.enum(PLATFORMS),
  externalId: z.string().trim().min(1, "An external account id is required.").max(120),
  name: z.string().trim().min(1, "A name is required.").max(160),
});

export async function createAccount(_prev: ActionState, formData: FormData): Promise<ActionState> {
  await requireArea("platform");
  const parsed = accountSchema.safeParse({
    platform: formData.get("platform"),
    externalId: formData.get("externalId"),
    name: formData.get("name"),
  });
  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid account." };

  const clash = await db.adsAccount.findUnique({
    where: { platform_externalId: { platform: parsed.data.platform, externalId: parsed.data.externalId } },
    select: { id: true },
  });
  if (clash) return { error: "An account with that platform + external id already exists." };

  try {
    await db.adsAccount.create({
      data: {
        platform: parsed.data.platform,
        externalId: parsed.data.externalId,
        name: parsed.data.name,
        status: "DISCONNECTED",
      },
    });
  } catch (err) {
    await logEvent("error", "ads.account.create", { message: String(err) });
    return { error: "Could not create the account." };
  }
  revalidatePath("/admin/ads/accounts");
  revalidatePath("/admin/ads");
  return { ok: true };
}

/**
 * "Connect" a stub account. This does NOT run OAuth or hit any platform — it
 * only marks the account CONNECTED_STUB so the rest of the UI can demonstrate a
 * connected flow. Real connection is gated on platform API approval.
 */
export async function connectAccountStub(id: string): Promise<ActionState> {
  await requireArea("platform");
  await db.adsAccount
    .update({ where: { id }, data: { status: "CONNECTED_STUB", connectedAt: new Date() } })
    .catch(() => null);
  await logEvent("info", "ads.account.connect_stub", { id });
  revalidatePath("/admin/ads/accounts");
  revalidatePath("/admin/ads");
  return { ok: true };
}

export async function disconnectAccount(id: string): Promise<ActionState> {
  await requireArea("platform");
  await db.adsAccount
    .update({ where: { id }, data: { status: "DISCONNECTED", connectedAt: null } })
    .catch(() => null);
  revalidatePath("/admin/ads/accounts");
  revalidatePath("/admin/ads");
  return { ok: true };
}

export async function deleteAccount(id: string): Promise<ActionState> {
  await requireArea("platform");
  await db.adsAccount.delete({ where: { id } }).catch(() => null);
  revalidatePath("/admin/ads/accounts");
  revalidatePath("/admin/ads");
  return { ok: true };
}

// ---------------------------------------------------------------------------
// Campaigns (local drafts)
// ---------------------------------------------------------------------------

const campaignSchema = z.object({
  accountId: z.string().trim().min(1, "Choose an account."),
  name: z.string().trim().min(1, "A campaign name is required.").max(160),
  objective: z.string().trim().max(80).default(""),
  dailyBudget: z.coerce.number().min(0, "Budget cannot be negative.").default(0),
});

export async function createCampaign(_prev: ActionState, formData: FormData): Promise<ActionState> {
  await requireArea("platform");
  const parsed = campaignSchema.safeParse({
    accountId: formData.get("accountId"),
    name: formData.get("name"),
    objective: formData.get("objective") ?? "",
    dailyBudget: formData.get("dailyBudget") ?? 0,
  });
  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid campaign." };

  const account = await db.adsAccount.findUnique({
    where: { id: parsed.data.accountId },
    select: { id: true, platform: true },
  });
  if (!account) return { error: "That account no longer exists." };

  try {
    await db.adsCampaign.create({
      data: {
        accountId: account.id,
        platform: account.platform,
        name: parsed.data.name,
        objective: parsed.data.objective,
        dailyBudgetCents: Math.round(parsed.data.dailyBudget * 100),
        status: "DRAFT",
      },
    });
  } catch (err) {
    await logEvent("error", "ads.campaign.create", { message: String(err) });
    return { error: "Could not create the campaign." };
  }
  revalidatePath("/admin/ads/campaigns");
  revalidatePath("/admin/ads");
  return { ok: true };
}

export async function setCampaignStatus(id: string, status: string): Promise<ActionState> {
  await requireArea("platform");
  if (!(ENTITY_STATUSES as readonly string[]).includes(status)) return { error: "Invalid status." };
  await db.adsCampaign
    .update({ where: { id }, data: { status: status as (typeof ENTITY_STATUSES)[number] } })
    .catch(() => null);
  revalidatePath("/admin/ads/campaigns");
  return { ok: true };
}

export async function deleteCampaign(id: string): Promise<ActionState> {
  await requireArea("platform");
  await db.adsCampaign.delete({ where: { id } }).catch(() => null);
  revalidatePath("/admin/ads/campaigns");
  revalidatePath("/admin/ads");
  return { ok: true };
}

// ---------------------------------------------------------------------------
// Ad sets / creatives / ads (local drafts)
// ---------------------------------------------------------------------------

const adSetSchema = z.object({
  campaignId: z.string().trim().min(1, "Choose a campaign."),
  name: z.string().trim().min(1, "An ad set name is required.").max(160),
  budget: z.coerce.number().min(0).default(0),
});

export async function createAdSet(_prev: ActionState, formData: FormData): Promise<ActionState> {
  await requireArea("platform");
  const parsed = adSetSchema.safeParse({
    campaignId: formData.get("campaignId"),
    name: formData.get("name"),
    budget: formData.get("budget") ?? 0,
  });
  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid ad set." };

  const campaign = await db.adsCampaign.findUnique({ where: { id: parsed.data.campaignId }, select: { id: true } });
  if (!campaign) return { error: "That campaign no longer exists." };

  await db.adsAdSet.create({
    data: {
      campaignId: campaign.id,
      name: parsed.data.name,
      budgetCents: Math.round(parsed.data.budget * 100),
      status: "DRAFT",
    },
  });
  revalidatePath("/admin/ads/campaigns");
  return { ok: true };
}

export async function deleteAdSet(id: string): Promise<ActionState> {
  await requireArea("platform");
  await db.adsAdSet.delete({ where: { id } }).catch(() => null);
  revalidatePath("/admin/ads/campaigns");
  return { ok: true };
}

const creativeSchema = z.object({
  adSetId: z.string().trim().min(1, "Choose an ad set."),
  name: z.string().trim().min(1, "A creative name is required.").max(160),
  headline: z.string().trim().max(200).default(""),
  body: z.string().trim().max(600).default(""),
});

export async function createCreative(_prev: ActionState, formData: FormData): Promise<ActionState> {
  await requireArea("platform");
  const parsed = creativeSchema.safeParse({
    adSetId: formData.get("adSetId"),
    name: formData.get("name"),
    headline: formData.get("headline") ?? "",
    body: formData.get("body") ?? "",
  });
  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid creative." };

  const adSet = await db.adsAdSet.findUnique({ where: { id: parsed.data.adSetId }, select: { id: true } });
  if (!adSet) return { error: "That ad set no longer exists." };

  await db.adsCreative.create({
    data: {
      adSetId: adSet.id,
      name: parsed.data.name,
      headline: parsed.data.headline,
      body: parsed.data.body,
      status: "DRAFT",
    },
  });
  revalidatePath("/admin/ads/campaigns");
  return { ok: true };
}

export async function deleteCreative(id: string): Promise<ActionState> {
  await requireArea("platform");
  await db.adsCreative.delete({ where: { id } }).catch(() => null);
  revalidatePath("/admin/ads/campaigns");
  return { ok: true };
}

const adSchema = z.object({
  creativeId: z.string().trim().min(1, "Choose a creative."),
  name: z.string().trim().min(1, "An ad name is required.").max(160),
});

/** Create an ad = place a creative in its ad set. Local draft only. */
export async function createAd(_prev: ActionState, formData: FormData): Promise<ActionState> {
  await requireArea("platform");
  const parsed = adSchema.safeParse({
    creativeId: formData.get("creativeId"),
    name: formData.get("name"),
  });
  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid ad." };

  const creative = await db.adsCreative.findUnique({
    where: { id: parsed.data.creativeId },
    select: { id: true, adSetId: true },
  });
  if (!creative) return { error: "That creative no longer exists." };

  await db.adsAd.create({
    data: { adSetId: creative.adSetId, creativeId: creative.id, name: parsed.data.name, status: "DRAFT" },
  });
  revalidatePath("/admin/ads/campaigns");
  return { ok: true };
}

export async function deleteAd(id: string): Promise<ActionState> {
  await requireArea("platform");
  await db.adsAd.delete({ where: { id } }).catch(() => null);
  revalidatePath("/admin/ads/campaigns");
  return { ok: true };
}

// ---------------------------------------------------------------------------
// Rules (create / toggle / DRY-RUN test)
// ---------------------------------------------------------------------------

const ruleSchema = z.object({
  accountId: z.string().trim().min(1, "Choose an account."),
  name: z.string().trim().min(1, "A rule name is required.").max(160),
  metric: z.enum(RULE_METRICS),
  operator: z.enum(RULE_OPERATORS),
  threshold: z.coerce.number(),
  lookbackDays: z.coerce.number().int().min(1).max(90).default(7),
  minImpressions: z.coerce.number().int().min(0).default(0),
  action: z.enum(RULE_ACTIONS),
  amountPct: z.coerce.number().min(0).max(1000).default(20),
});

export async function createRule(_prev: ActionState, formData: FormData): Promise<ActionState> {
  await requireArea("platform");
  const parsed = ruleSchema.safeParse({
    accountId: formData.get("accountId"),
    name: formData.get("name"),
    metric: formData.get("metric"),
    operator: formData.get("operator"),
    threshold: formData.get("threshold"),
    lookbackDays: formData.get("lookbackDays") ?? 7,
    minImpressions: formData.get("minImpressions") ?? 0,
    action: formData.get("action"),
    amountPct: formData.get("amountPct") ?? 20,
  });
  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid rule." };

  const account = await db.adsAccount.findUnique({ where: { id: parsed.data.accountId }, select: { id: true } });
  if (!account) return { error: "That account no longer exists." };

  const whenJson: Prisma.InputJsonValue = {
    metric: parsed.data.metric,
    operator: parsed.data.operator,
    threshold: parsed.data.threshold,
    lookbackDays: parsed.data.lookbackDays,
    minImpressions: parsed.data.minImpressions,
  };
  const thenJson: Prisma.InputJsonValue = {
    action: parsed.data.action,
    ...(parsed.data.action === "raise_budget" || parsed.data.action === "lower_budget"
      ? { amountPct: parsed.data.amountPct }
      : {}),
  };

  try {
    await db.adsRule.create({
      data: { accountId: account.id, name: parsed.data.name, whenJson, thenJson, enabled: false },
    });
  } catch (err) {
    await logEvent("error", "ads.rule.create", { message: String(err) });
    return { error: "Could not create the rule." };
  }
  revalidatePath("/admin/ads/rules");
  revalidatePath("/admin/ads");
  return { ok: true };
}

export async function toggleRule(id: string, enabled: boolean): Promise<ActionState> {
  await requireArea("platform");
  await db.adsRule.update({ where: { id }, data: { enabled } }).catch(() => null);
  revalidatePath("/admin/ads/rules");
  return { ok: true };
}

export async function deleteRule(id: string): Promise<ActionState> {
  await requireArea("platform");
  await db.adsRule.delete({ where: { id } }).catch(() => null);
  revalidatePath("/admin/ads/rules");
  revalidatePath("/admin/ads");
  return { ok: true };
}

/**
 * Test a rule as a DRY-RUN. Pulls the account's campaign-scope insights over the
 * rule's lookback window, runs the pure evaluator, and records an AdsRuleRun
 * with the human note of what it WOULD do. Executes NO platform mutation.
 */
export async function testRuleDryRun(id: string): Promise<ActionState> {
  await requireArea("platform");
  const rule = await db.adsRule.findUnique({ where: { id }, select: { id: true, accountId: true, whenJson: true, thenJson: true } });
  if (!rule) return { error: "That rule no longer exists." };

  const when = (rule.whenJson ?? {}) as { lookbackDays?: number };
  const lookbackDays = Math.max(1, Math.round(Number(when.lookbackDays) || 7));
  const since = new Date(Date.now() - lookbackDays * 24 * 60 * 60 * 1000);

  const insights = await db.adsInsight.findMany({
    where: {
      scope: "CAMPAIGN",
      date: { gte: since },
      campaign: { accountId: rule.accountId },
    },
    select: { impressions: true, clicks: true, spendCents: true, conversions: true },
  });

  const rows: InsightCounters[] = insights.map((r) => ({
    impressions: r.impressions,
    clicks: r.clicks,
    spendCents: r.spendCents,
    conversions: r.conversions,
  }));

  const result = evaluateRule(rule.whenJson, rule.thenJson, rows);

  await db.adsRuleRun.create({ data: { ruleId: rule.id, matched: result.matched, note: result.note } });
  await logEvent("info", "ads.rule.dry_run", { id: rule.id, matched: result.matched });
  revalidatePath("/admin/ads/rules");
  return { ok: true, note: result.note };
}

