"use client";

/**
 * Adloop — admin client controls (forms + row actions). PHASE 1.
 *
 * Thin wrappers over lib/actions-ads.ts. No control here reaches a live ad
 * platform: "Connect" marks a stub, "Test rule" runs the dry-run evaluator.
 */

import { useActionState, useEffect, useRef, useState, useTransition } from "react";
import {
  createAccount,
  connectAccountStub,
  disconnectAccount,
  deleteAccount,
  createCampaign,
  setCampaignStatus,
  deleteCampaign,
  createAdSet,
  deleteAdSet,
  createCreative,
  deleteCreative,
  createAd,
  deleteAd,
  createRule,
  toggleRule,
  deleteRule,
  testRuleDryRun,
} from "@/lib/actions-ads";

type State = { error?: string; ok?: boolean; note?: string };
const EMPTY: State = {};

function Banner({ state, okText }: { state: State; okText: string }) {
  if (state?.error) {
    return (
      <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
        {state.error}
      </div>
    );
  }
  if (state?.ok) {
    return (
      <div className="rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">
        {state.note ?? okText}
      </div>
    );
  }
  return null;
}

/** A button that runs a () => Promise action inside a transition. */
function ActionButton({
  run,
  children,
  className = "",
  confirm,
  title,
  onResult,
}: {
  run: () => Promise<State>;
  children: React.ReactNode;
  className?: string;
  confirm?: string;
  title?: string;
  onResult?: (r: State) => void;
}) {
  const [pending, start] = useTransition();
  const [err, setErr] = useState<string | null>(null);
  return (
    <span className="inline-flex flex-col items-end">
      <button
        type="button"
        disabled={pending}
        title={title}
        className={className || "btn-ghost text-xs"}
        onClick={() => {
          if (confirm && !window.confirm(confirm)) return;
          setErr(null);
          start(async () => {
            const r = await run();
            if (r?.error) setErr(r.error);
            onResult?.(r);
          });
        }}
      >
        {pending ? "Working…" : children}
      </button>
      {err && <span className="mt-1 text-[11px] text-red-400">{err}</span>}
    </span>
  );
}

// ---------------------------------------------------------------------------
// Accounts
// ---------------------------------------------------------------------------

const PLATFORMS = [
  { value: "META", label: "Meta" },
  { value: "TIKTOK", label: "TikTok" },
  { value: "GOOGLE", label: "Google" },
];

export function AccountCreateForm() {
  const [state, action] = useActionState(createAccount, EMPTY);
  const ref = useRef<HTMLFormElement>(null);
  useEffect(() => {
    if (state?.ok) ref.current?.reset();
  }, [state]);
  return (
    <form ref={ref} action={action} className="space-y-4">
      <Banner state={state} okText="Account added." />
      <div className="grid gap-4 sm:grid-cols-3">
        <div>
          <label className="label">Platform</label>
          <select name="platform" className="input" required>
            {PLATFORMS.map((p) => (
              <option key={p.value} value={p.value}>
                {p.label}
              </option>
            ))}
          </select>
        </div>
        <div>
          <label className="label">External account id</label>
          <input name="externalId" className="input" placeholder="act_1234567890" required />
        </div>
        <div>
          <label className="label">Name</label>
          <input name="name" className="input" placeholder="Acme — Meta" required />
        </div>
      </div>
      <button type="submit" className="btn-primary text-sm">
        Add account
      </button>
    </form>
  );
}

export function AccountRowActions({ id, status }: { id: string; status: string }) {
  return (
    <div className="flex flex-wrap items-center justify-end gap-2">
      {status === "CONNECTED_STUB" ? (
        <ActionButton
          run={() => disconnectAccount(id)}
          className="btn-ghost text-xs"
          title="Revert to disconnected"
        >
          Disconnect
        </ActionButton>
      ) : (
        <ActionButton
          run={() => connectAccountStub(id)}
          confirm="Connect this account? Phase 1 stub — no OAuth runs and no platform is contacted; it only marks the account as connected."
          className="btn-primary text-xs"
          title="Phase 1 stub — marks CONNECTED_STUB, no network call"
        >
          Connect (stub)
        </ActionButton>
      )}
      <ActionButton
        run={() => deleteAccount(id)}
        confirm="Delete this account and everything under it?"
        className="btn-ghost text-xs text-red-400"
      >
        Delete
      </ActionButton>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Campaigns
// ---------------------------------------------------------------------------

export function CampaignCreateForm({ accounts }: { accounts: { id: string; name: string; platform: string }[] }) {
  const [state, action] = useActionState(createCampaign, EMPTY);
  const ref = useRef<HTMLFormElement>(null);
  useEffect(() => {
    if (state?.ok) ref.current?.reset();
  }, [state]);
  return (
    <form ref={ref} action={action} className="space-y-4">
      <Banner state={state} okText="Campaign created." />
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <div>
          <label className="label">Account</label>
          <select name="accountId" className="input" required>
            <option value="">Choose…</option>
            {accounts.map((a) => (
              <option key={a.id} value={a.id}>
                {a.name} ({a.platform.toLowerCase()})
              </option>
            ))}
          </select>
        </div>
        <div>
          <label className="label">Name</label>
          <input name="name" className="input" placeholder="Spring sale" required />
        </div>
        <div>
          <label className="label">Objective</label>
          <input name="objective" className="input" placeholder="OUTCOME_SALES" />
        </div>
        <div>
          <label className="label">Daily budget ($)</label>
          <input name="dailyBudget" type="number" min="0" step="0.01" className="input" placeholder="50.00" />
        </div>
      </div>
      <button type="submit" className="btn-primary text-sm">
        Add campaign
      </button>
    </form>
  );
}

const ENTITY_STATUSES = ["DRAFT", "ACTIVE", "PAUSED", "ARCHIVED"];

export function CampaignRowActions({ id, status }: { id: string; status: string }) {
  const [pending, start] = useTransition();
  return (
    <div className="flex flex-wrap items-center justify-end gap-2">
      <select
        defaultValue={status}
        disabled={pending}
        className="input h-8 py-0 text-xs"
        onChange={(e) => {
          const next = e.target.value;
          start(async () => {
            await setCampaignStatus(id, next);
          });
        }}
      >
        {ENTITY_STATUSES.map((s) => (
          <option key={s} value={s}>
            {s.toLowerCase()}
          </option>
        ))}
      </select>
      <ActionButton
        run={() => deleteCampaign(id)}
        confirm="Delete this campaign and its ad sets/ads?"
        className="btn-ghost text-xs text-red-400"
      >
        Delete
      </ActionButton>
    </div>
  );
}

export function AdSetCreateForm({ campaignId }: { campaignId: string }) {
  const [state, action] = useActionState(createAdSet, EMPTY);
  const ref = useRef<HTMLFormElement>(null);
  useEffect(() => {
    if (state?.ok) ref.current?.reset();
  }, [state]);
  return (
    <form ref={ref} action={action} className="mt-2 flex flex-wrap items-end gap-2">
      <input type="hidden" name="campaignId" value={campaignId} />
      <div>
        <label className="label">New ad set</label>
        <input name="name" className="input h-8 py-0 text-xs" placeholder="Ad set name" required />
      </div>
      <div>
        <label className="label">Budget ($)</label>
        <input name="budget" type="number" min="0" step="0.01" className="input h-8 w-24 py-0 text-xs" />
      </div>
      <button type="submit" className="btn-ghost text-xs">
        Add
      </button>
      {state?.error && <span className="text-[11px] text-red-400">{state.error}</span>}
    </form>
  );
}

export function AdSetRowActions({ id }: { id: string }) {
  return (
    <ActionButton run={() => deleteAdSet(id)} confirm="Delete this ad set?" className="btn-ghost text-xs text-red-400">
      Delete
    </ActionButton>
  );
}

export function CreativeCreateForm({ adSetId }: { adSetId: string }) {
  const [state, action] = useActionState(createCreative, EMPTY);
  const ref = useRef<HTMLFormElement>(null);
  useEffect(() => {
    if (state?.ok) ref.current?.reset();
  }, [state]);
  return (
    <form ref={ref} action={action} className="mt-2 grid gap-2 sm:grid-cols-2">
      <input type="hidden" name="adSetId" value={adSetId} />
      <input name="name" className="input h-8 py-0 text-xs" placeholder="Creative name" required />
      <input name="headline" className="input h-8 py-0 text-xs" placeholder="Headline" />
      <textarea name="body" className="input min-h-[48px] text-xs sm:col-span-2" placeholder="Body copy" />
      <div className="sm:col-span-2 flex items-center gap-2">
        <button type="submit" className="btn-ghost text-xs">
          Add creative
        </button>
        {state?.error && <span className="text-[11px] text-red-400">{state.error}</span>}
      </div>
    </form>
  );
}

export function CreativeRowActions({ id, adSetId }: { id: string; adSetId: string }) {
  const [name, setName] = useState("");
  return (
    <div className="flex flex-wrap items-center justify-end gap-2">
      <input
        value={name}
        onChange={(e) => setName(e.target.value)}
        className="input h-8 w-32 py-0 text-xs"
        placeholder="Ad name"
      />
      <ActionButton
        run={async () => {
          const fd = new FormData();
          fd.set("creativeId", id);
          fd.set("name", name || "New ad");
          return createAd(EMPTY, fd);
        }}
        className="btn-ghost text-xs"
        title="Create an ad from this creative (local draft)"
        onResult={(r) => {
          if (r?.ok) setName("");
        }}
      >
        Make ad
      </ActionButton>
      <ActionButton run={() => deleteCreative(id)} confirm="Delete this creative?" className="btn-ghost text-xs text-red-400">
        Delete
      </ActionButton>
    </div>
  );
}

export function AdRowActions({ id }: { id: string }) {
  return (
    <ActionButton run={() => deleteAd(id)} confirm="Delete this ad?" className="btn-ghost text-xs text-red-400">
      Delete
    </ActionButton>
  );
}

// ---------------------------------------------------------------------------
// Rules
// ---------------------------------------------------------------------------

const METRICS = ["spend", "impressions", "clicks", "conversions", "ctr", "cpc", "cpm", "cpa", "cvr"];
const OPERATORS = [
  { value: "gt", label: "> greater than" },
  { value: "gte", label: "≥ at least" },
  { value: "lt", label: "< less than" },
  { value: "lte", label: "≤ at most" },
  { value: "eq", label: "= equals" },
];
const ACTIONS = [
  { value: "pause", label: "Pause" },
  { value: "enable", label: "Enable" },
  { value: "raise_budget", label: "Raise budget" },
  { value: "lower_budget", label: "Lower budget" },
  { value: "notify", label: "Notify" },
];

export function RuleCreateForm({ accounts }: { accounts: { id: string; name: string; platform: string }[] }) {
  const [state, action] = useActionState(createRule, EMPTY);
  const ref = useRef<HTMLFormElement>(null);
  useEffect(() => {
    if (state?.ok) ref.current?.reset();
  }, [state]);
  return (
    <form ref={ref} action={action} className="space-y-4">
      <Banner state={state} okText="Rule created (disabled by default)." />
      <div className="grid gap-4 sm:grid-cols-2">
        <div>
          <label className="label">Account</label>
          <select name="accountId" className="input" required>
            <option value="">Choose…</option>
            {accounts.map((a) => (
              <option key={a.id} value={a.id}>
                {a.name} ({a.platform.toLowerCase()})
              </option>
            ))}
          </select>
        </div>
        <div>
          <label className="label">Rule name</label>
          <input name="name" className="input" placeholder="Pause high-CPA campaigns" required />
        </div>
      </div>

      <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] p-4">
        <p className="section-label mb-3">When (condition)</p>
        <div className="grid gap-4 sm:grid-cols-3 lg:grid-cols-5">
          <div>
            <label className="label">Metric</label>
            <select name="metric" className="input" required>
              {METRICS.map((m) => (
                <option key={m} value={m}>
                  {m}
                </option>
              ))}
            </select>
          </div>
          <div>
            <label className="label">Operator</label>
            <select name="operator" className="input" required>
              {OPERATORS.map((o) => (
                <option key={o.value} value={o.value}>
                  {o.label}
                </option>
              ))}
            </select>
          </div>
          <div>
            <label className="label">Threshold</label>
            <input name="threshold" type="number" step="any" className="input" placeholder="25" required />
          </div>
          <div>
            <label className="label">Lookback (days)</label>
            <input name="lookbackDays" type="number" min="1" max="90" defaultValue={7} className="input" />
          </div>
          <div>
            <label className="label">Min impressions</label>
            <input name="minImpressions" type="number" min="0" defaultValue={1000} className="input" />
          </div>
        </div>
      </div>

      <div className="rounded-xl border border-white/[0.06] bg-white/[0.02] p-4">
        <p className="section-label mb-3">Then (action — dry-run only in Phase 1)</p>
        <div className="grid gap-4 sm:grid-cols-2">
          <div>
            <label className="label">Action</label>
            <select name="action" className="input" required>
              {ACTIONS.map((a) => (
                <option key={a.value} value={a.value}>
                  {a.label}
                </option>
              ))}
            </select>
          </div>
          <div>
            <label className="label">Amount % (budget actions)</label>
            <input name="amountPct" type="number" min="0" max="1000" defaultValue={20} className="input" />
          </div>
        </div>
      </div>

      <button type="submit" className="btn-primary text-sm">
        Create rule
      </button>
    </form>
  );
}

export function RuleRowActions({ id, enabled }: { id: string; enabled: boolean }) {
  const [note, setNote] = useState<string | null>(null);
  return (
    <div className="flex flex-col items-end gap-1">
      <div className="flex flex-wrap items-center justify-end gap-2">
        <ActionButton
          run={() => toggleRule(id, !enabled)}
          className="btn-ghost text-xs"
          title={enabled ? "Disable this rule" : "Enable this rule"}
        >
          {enabled ? "Disable" : "Enable"}
        </ActionButton>
        <ActionButton
          run={() => testRuleDryRun(id)}
          className="btn-primary text-xs"
          title="Evaluate against current sample insights — never executes"
          onResult={(r) => setNote(r?.note ?? null)}
        >
          Test rule (dry-run)
        </ActionButton>
        <ActionButton run={() => deleteRule(id)} confirm="Delete this rule?" className="btn-ghost text-xs text-red-400">
          Delete
        </ActionButton>
      </div>
      {note && (
        <span className="max-w-md text-right text-[11px] text-amber-300">{note}</span>
      )}
    </div>
  );
}

