export const dynamic = "force-dynamic";

const OP_LABEL: Record<string, string> = { gt: ">", gte: "≥", lt: "<", lte: "≤", eq: "=" };

export default async function AdsRules() {
  await requireArea("platform");

  const [rules, accounts] = await Promise.all([
    db.adsRule.findMany({
      orderBy: { createdAt: "desc" },
      include: {
        account: { select: { name: true, platform: true } },
        runs: { orderBy: { ranAt: "desc" }, take: 1 },
      },
      take: 200,
    }),
    db.adsAccount.findMany({ orderBy: { name: "asc" }, select: { id: true, name: true, platform: true } }),
  ]);

  return (
    <div className="space-y-6">
      <PageHeader
        title="Rules"
        sub="Automation rules (when/then). Phase 1 evaluates them dry-run only — a matched rule shows what it WOULD do but never executes a real change."
      />

      <div className="rounded-xl border border-amber-500/30 bg-amber-500/10 p-4 text-sm text-amber-300">
        Rules never mutate a live platform in Phase 1. “Test rule (dry-run)” evaluates the condition against
        current sample insights, records the outcome, and reports the action it would have taken. Real
        execution ships with the write-ops layer once platform API access clears.
      </div>

      <div className="card">
        <p className="section-label mb-4">Create a rule</p>
        {accounts.length === 0 ? (
          <p className="text-sm text-slate-400">Add an ad account first on the Accounts tab.</p>
        ) : (
          <RuleCreateForm accounts={accounts} />
