      {rules.length === 0 ? (
        <EmptyState title="No rules yet" sub="Create one above to see the dry-run evaluator in action." />
      ) : (
        <div className="card overflow-x-auto p-0">
          <table className="table-shell mt-2 min-w-[900px]">
            <thead>
              <tr>
                <th>Rule</th>
                <th>Account</th>
                <th>When</th>
                <th>Then</th>
                <th>Enabled</th>
                <th>Last dry-run</th>
                <th className="text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {rules.map((r) => {
                const cond = coerceCondition(r.whenJson);
                const then = coerceThen(r.thenJson);
                const last = r.runs[0];
                return (
                  <tr key={r.id}>
                    <td className="align-top font-medium text-white">{r.name}</td>
                    <td className="align-top text-slate-400">
                      {r.account.name}
                      <div className="text-xs text-slate-600">{r.account.platform.toLowerCase()}</div>
                    </td>
                    <td className="align-top text-slate-300">
                      {cond.metric} {OP_LABEL[cond.operator]} {formatMetric(cond.metric, cond.threshold)}
                      <div className="text-xs text-slate-600">
                        {cond.lookbackDays}d · min {cond.minImpressions} impr
                      </div>
                    </td>
                    <td className="align-top text-slate-300">{describeAction(then)}</td>
                    <td className="align-top">
                      {r.enabled ? <Badge tone="green">enabled</Badge> : <Badge tone="slate">disabled</Badge>}
                    </td>
                    <td className="align-top text-xs text-slate-400">
                      {last ? (
                        <>
                          <Badge tone={last.matched ? "amber" : "slate"}>{last.matched ? "matched" : "no match"}</Badge>
                          <div className="mt-1 text-slate-600">{timeAgo(last.ranAt)}</div>
                        </>
                      ) : (
                        <span className="text-slate-600">never</span>
                      )}
                    </td>
                    <td className="align-top">
                      <RuleRowActions id={r.id} enabled={r.enabled} />
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

/**
 * Adloop (Ads Autopilot) — seed sample accounts, campaigns and insights.
 *
 * Idempotent-ish: clears and re-inserts the two demo accounts (by their stub
 * externalId) so the dashboard renders with data on staging. NOT run by any
 * deploy — run manually against a chosen target, exactly like prisma/seed.ts:
 *
 *   NXEON_DB_TARGET=nxeon_staging npx tsx prisma/seed-ads.ts
 *
 * GUARDRAILS: no network, no OAuth, no ad spend. The "CONNECTED_STUB" status is
 * cosmetic — nothing here contacts Meta / TikTok / Google.
 */

import { PrismaClient } from "@prisma/client";
import { assertDbTarget } from "../scripts/db-target-guard.ts";

assertDbTarget("prisma/seed-ads.ts");

const db = new PrismaClient();

/** Deterministic-ish daily counters so the dashboard + rules have real numbers. */
function dailyRows(days: number, base: { impr: number; ctr: number; cpc: number; cvr: number }) {
  const rows: { date: Date; impressions: number; clicks: number; spendCents: number; conversions: number }[] = [];
  for (let i = days - 1; i >= 0; i--) {
    const wobble = 1 + ((i % 5) - 2) * 0.06; // ±12% deterministic wobble
    const impressions = Math.round(base.impr * wobble);
    const clicks = Math.round(impressions * base.ctr);
    const spendCents = Math.round(clicks * base.cpc * 100);
    const conversions = Math.round(clicks * base.cvr);
    const date = new Date();
    date.setUTCHours(0, 0, 0, 0);
    date.setUTCDate(date.getUTCDate() - i);
    rows.push({ date, impressions, clicks, spendCents, conversions });
  }
  return rows;
}

async function seedAccount(opts: {
  platform: "META" | "TIKTOK" | "GOOGLE";
  externalId: string;
  name: string;
  campaign: { name: string; objective: string; dailyBudgetCents: number };
  metrics: { impr: number; ctr: number; cpc: number; cvr: number };
}) {
  // Remove a prior run for this stub account (cascades to its children).
  await db.adsAccount
    .delete({ where: { platform_externalId: { platform: opts.platform, externalId: opts.externalId } } })
    .catch(() => null);

  const account = await db.adsAccount.create({
    data: {
      platform: opts.platform,
      externalId: opts.externalId,
      name: opts.name,
      status: "CONNECTED_STUB",
      connectedAt: new Date(),
    },
  });

  const campaign = await db.adsCampaign.create({
    data: {
      accountId: account.id,
      platform: opts.platform,
      name: opts.campaign.name,
      objective: opts.campaign.objective,
      status: "ACTIVE",
      dailyBudgetCents: opts.campaign.dailyBudgetCents,
    },
  });

  const adSet = await db.adsAdSet.create({
    data: {
      campaignId: campaign.id,
      name: `${opts.campaign.name} — core audience`,
      budgetCents: opts.campaign.dailyBudgetCents,
      status: "ACTIVE",
      targetingJson: { geo: ["CA"], age: "25-54", placements: ["feed"] },
    },
  });

  const creative = await db.adsCreative.create({
    data: {
      adSetId: adSet.id,
      name: `${opts.campaign.name} — hero creative`,
      headline: "Your ads, on autopilot.",
      body: "Cross-platform campaign management with rules that run themselves.",
      status: "ACTIVE",
    },
  });

  await db.adsAd.create({
    data: { adSetId: adSet.id, creativeId: creative.id, name: `${opts.campaign.name} — ad 1`, status: "ACTIVE" },
  });

  const rows = dailyRows(14, opts.metrics);
  await db.adsInsight.createMany({
    data: rows.map((r) => ({ scope: "CAMPAIGN" as const, campaignId: campaign.id, ...r })),
  });

  // One sample automation rule per account (disabled; ready to dry-run).
  await db.adsRule.create({
    data: {
      accountId: account.id,
      name: "Pause when CPA is too high",
      whenJson: { metric: "cpa", operator: "gt", threshold: 40, lookbackDays: 7, minImpressions: 1000 },
      thenJson: { action: "pause" },
      enabled: false,
    },
  });

  console.log(`seeded ${opts.platform} account "${opts.name}" + campaign/adset/creative/ad + 14d insights + 1 rule`);
}

async function main() {
  await seedAccount({
    platform: "META",
    externalId: "act_1000000000001",
    name: "RevSports — Meta (demo)",
    campaign: { name: "Spring sale", objective: "OUTCOME_SALES", dailyBudgetCents: 5000 },
    metrics: { impr: 42000, ctr: 0.018, cpc: 0.62, cvr: 0.05 },
  });

  await seedAccount({
    platform: "GOOGLE",
    externalId: "123-456-7890",
    name: "RevSports — Google (demo)",
    campaign: { name: "Brand search", objective: "SEARCH", dailyBudgetCents: 8000 },
    metrics: { impr: 18000, ctr: 0.061, cpc: 1.35, cvr: 0.09 },
  });

  console.log("done — Adloop sample data seeded.");
}

main()
  .then(() => db.$disconnect())
  .catch(async (err) => {
    console.error(err);
    await db.$disconnect();
    process.exit(1);
  });

import { test } from "node:test";
import assert from "node:assert/strict";
import {
  evaluateRule,
  coerceCondition,
  coerceThen,
  describeAction,
} from "../lib/ads/rules-engine.ts";
import { deriveMetrics, sumCounters, formatMetric } from "../lib/ads/metrics.ts";
import { getConnector } from "../lib/ads/connectors/index.ts";
import type { InsightCounters } from "../lib/ads/types.ts";

/* ------------------------------------------------------------------ *
 * 1. Coercion never throws and always yields a valid shape
 * ------------------------------------------------------------------ */

test("coerceCondition defaults every field from garbage input", () => {
  const c = coerceCondition(null);
  assert.equal(c.metric, "cpa");
  assert.equal(c.operator, "gt");
  assert.equal(c.threshold, 0);
  assert.equal(c.lookbackDays, 7);
  assert.equal(c.minImpressions, 0);

  const c2 = coerceCondition({ metric: "bogus", operator: "??", threshold: "12.5", lookbackDays: "3" });
  assert.equal(c2.metric, "cpa"); // invalid metric falls back
  assert.equal(c2.operator, "gt");
  assert.equal(c2.threshold, 12.5); // numeric string coerced
  assert.equal(c2.lookbackDays, 3);
});

test("coerceThen only keeps amountPct for budget actions", () => {
  assert.deepEqual(coerceThen({ action: "pause", amountPct: 50 }), { action: "pause" });
  assert.deepEqual(coerceThen({ action: "raise_budget", amountPct: 30 }), { action: "raise_budget", amountPct: 30 });
  assert.equal(coerceThen({ action: "nonsense" }).action, "notify"); // invalid → notify
  assert.equal(coerceThen({ action: "raise_budget" }).amountPct, 20); // default pct
});

/* ------------------------------------------------------------------ *
 * 2. Metric derivation guards divide-by-zero
 * ------------------------------------------------------------------ */

test("deriveMetrics returns null (not NaN) for zero denominators", () => {
  const m = deriveMetrics({ impressions: 0, clicks: 0, spendCents: 0, conversions: 0 });
  assert.equal(m.ctr, null);
  assert.equal(m.cpc, null);
  assert.equal(m.cpm, null);
  assert.equal(m.cpa, null);
  assert.equal(m.cvr, null);
  assert.equal(m.spend, 0);
});

test("deriveMetrics computes canonical metrics correctly", () => {
  const m = deriveMetrics({ impressions: 1000, clicks: 50, spendCents: 5000, conversions: 5 });
  assert.equal(m.spend, 50);
  assert.equal(m.ctr, 0.05); // 50/1000
  assert.equal(m.cpc, 1); // $50/50
  assert.equal(m.cpm, 50); // $50/1000*1000
  assert.equal(m.cpa, 10); // $50/5
  assert.equal(m.cvr, 0.1); // 5/50
});

test("sumCounters aggregates rows", () => {
  const rows: InsightCounters[] = [
    { impressions: 100, clicks: 5, spendCents: 500, conversions: 1 },
    { impressions: 200, clicks: 10, spendCents: 1000, conversions: 2 },
  ];
  assert.deepEqual(sumCounters(rows), { impressions: 300, clicks: 15, spendCents: 1500, conversions: 3 });
});

/* ------------------------------------------------------------------ *
 * 3. Rule evaluation — the dry-run decision
 * ------------------------------------------------------------------ */

const rows: InsightCounters[] = [
  { impressions: 5000, clicks: 100, spendCents: 20000, conversions: 4 }, // spend $200, cpa $50
];

test("rule matches when CPA exceeds threshold", () => {
  const r = evaluateRule(
    { metric: "cpa", operator: "gt", threshold: 40, minImpressions: 1000 },
    { action: "pause" },
    rows,
  );
  assert.equal(r.matched, true);
  assert.equal(r.wouldDo, "pause");
  assert.equal(r.belowFloor, false);
  assert.match(r.note, /DRY-RUN/);
  assert.match(r.note, /would pause/);
});

test("rule does not match when condition is not met", () => {
  const r = evaluateRule(
    { metric: "cpa", operator: "lt", threshold: 40, minImpressions: 1000 },
    { action: "pause" },
    rows,
  );
  assert.equal(r.matched, false);
  assert.equal(r.wouldDo, null);
  assert.match(r.note, /No match/);
});

test("significance floor blocks evaluation on thin data", () => {
  const thin: InsightCounters[] = [{ impressions: 200, clicks: 4, spendCents: 800, conversions: 1 }];
  const r = evaluateRule(
    { metric: "cpa", operator: "gt", threshold: 1, minImpressions: 1000 },
    { action: "pause" },
    thin,
  );
  assert.equal(r.matched, false);
  assert.equal(r.belowFloor, true);
  assert.match(r.note, /significance floor/);
});

test("null metric (no conversions) is reported, not matched", () => {
  const noConv: InsightCounters[] = [{ impressions: 5000, clicks: 100, spendCents: 20000, conversions: 0 }];
  const r = evaluateRule(
    { metric: "cpa", operator: "gt", threshold: 1, minImpressions: 1000 },
    { action: "pause" },
    noConv,
  );
  assert.equal(r.matched, false);
  assert.equal(r.computed, null);
  assert.match(r.note, /could not be computed/);
});

test("raise_budget action is described with its percentage", () => {
  const r = evaluateRule(
    { metric: "cvr", operator: "gte", threshold: 0.01, minImpressions: 1000 },
    { action: "raise_budget", amountPct: 25 },
    rows,
  );
  assert.equal(r.matched, true);
  assert.match(r.note, /raise the daily budget by 25%/);
});

test("empty insight set never throws and does not match", () => {
  const r = evaluateRule({ metric: "spend", operator: "gt", threshold: 0 }, { action: "notify" }, []);
  assert.equal(r.matched, false);
  assert.equal(r.computed, 0); // spend has no denominator, defaults to 0
});

test("describeAction covers every action", () => {
  assert.match(describeAction({ action: "pause" }), /pause/);
  assert.match(describeAction({ action: "enable" }), /enable/);
  assert.match(describeAction({ action: "lower_budget", amountPct: 10 }), /lower/);
  assert.match(describeAction({ action: "notify" }), /notification/);
});

