test("every connector returns a typed not-ready result", async () => {
  for (const p of ["META", "TIKTOK", "GOOGLE"] as const) {
    const conn = getConnector(p);
    assert.equal(conn.platform, p);
    const accounts = await conn.listAccounts();
    assert.equal(accounts.ok, false);
    if (!accounts.ok) {
      assert.equal(accounts.reason, "pending_approval");
      assert.match(accounts.message, /pending platform API approval/);
    }
    const campaigns = await conn.listCampaigns("act_1");
    assert.equal(campaigns.ok, false);
    const insights = await conn.fetchInsights("c_1", 7);
    assert.equal(insights.ok, false);
  }
});

